int sc_get_data(sc_card_t *card, unsigned int tag, u8 *buf, size_t len)
{
        int     r;

        sc_log(card->ctx, "called, tag=%04x", tag);
        if (card->ops->get_data == NULL)
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
        r = card->ops->get_data(card, tag, buf, len);

        LOG_FUNC_RETURN(card->ctx, r);
}

int sc_put_data(sc_card_t *card, unsigned int tag, const u8 *buf, size_t len)
{
        int     r;

        sc_log(card->ctx,"called, tag=%04x", tag);

        if (card->ops->put_data == NULL)
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
        r = card->ops->put_data(card, tag, buf, len);

        LOG_FUNC_RETURN(card->ctx, r);
}

int sc_get_challenge(sc_card_t *card, u8 *rnd, size_t len)
{
        int r;
        size_t retry = 10;

        if (len == 0)
                return SC_SUCCESS;

        if (card == NULL || rnd == NULL) {
                return SC_ERROR_INVALID_ARGUMENTS;
        }

        LOG_FUNC_CALLED(card->ctx);

        if (card->ops == NULL || card->ops->get_challenge == NULL)
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);

        r = sc_lock(card);
        if (r != SC_SUCCESS)
                LOG_FUNC_RETURN(card->ctx, r);

pgp_get_data(sc_card_t *card, unsigned int tag, u8 *buf, size_t buf_len)
{
        sc_apdu_t       apdu;
        int             r;

        LOG_FUNC_CALLED(card->ctx);

        sc_format_apdu(card, &apdu, SC_APDU_CASE_2, 0xCA, tag >> 8, tag);
        apdu.le = ((buf_len >= 256) && !(card->caps & SC_CARD_CAP_APDU_EXT)) ? 256 : buf_len;
        apdu.resp = buf;
        apdu.resplen = buf_len;

        r = sc_transmit_apdu(card, &apdu);
        LOG_TEST_RET(card->ctx, r, "APDU transmit failed");

        r = sc_check_sw(card, apdu.sw1, apdu.sw2);

        /* Gnuk returns an error instead of empty data if there is no certificate or private DO.
         * So, for this case, we ignore error and consider success */
        if (card->type == SC_CARD_TYPE_OPENPGP_GNUK &&
            (tag == DO_CERT  ||
             tag == DO_PRIV1 ||
             tag == DO_PRIV2 ||
             tag == DO_PRIV3 ||
             tag == DO_PRIV4)) {
                if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
                        r = SC_SUCCESS;
                        apdu.resplen = 0;
                }
        }
        LOG_TEST_RET(card->ctx, r, "Card returned error");

        LOG_FUNC_RETURN(card->ctx, (int)apdu.resplen);
}


